import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Html, Line, OrbitControls, RoundedBox } from "@react-three/drei";
import * as THREE from "three";
import { Activity, AlertTriangle, Pause, Play, RefreshCw, Wifi, WifiOff } from "lucide-react";

type Status = "normal" | "attention" | "critical";
type Kind = "supply" | "medication" | "patient" | "data";
type Area = { id:string; name:string; type:string; position:[number,number,number]; size:[number,number,number]; status:Status; metrics:Record<string,number|undefined> };
type Flow = { id:string; from:string; to:string; kind:Kind; volume:number; status?:Status };
type TwinEvent = { id:string; type:string; from?:string|null; to?:string|null; areaId?:string|null; occurredAt:string; severity:Status; metadata?:Record<string,string|number|boolean|null> };
type Snapshot = { hospitalId:string; generatedAt:string; source:"demo"|"remote"; areas:Area[]; flows:Flow[]; summary:{areas:number;criticalAreas:number;attentionAreas:number;activeFlows:number} };
type EventBatch = { generatedAt:string; source:"demo"|"remote"; events:TwinEvent[]; nextCursor:string|null };

const statusColor:Record<Status,string>={normal:"#006f7b",attention:"#ad7a00",critical:"#9d2f36"};
const flowColor:Record<Kind,string>={supply:"#7dd3fc",medication:"#f0b95c",patient:"#c4b5fd",data:"#a7f3d0"};
const labels:Record<Kind,string>={supply:"Abastecimiento",medication:"Medicamentos",patient:"Pacientes",data:"Datos"};

function FlowDot({flow,paused,index,areasById}:{flow:Flow;paused:boolean;index:number;areasById:Map<string,Area>}){
 const ref=useRef<THREE.Mesh>(null); const t=useRef((index*.31)%1); const from=areasById.get(flow.from); const to=areasById.get(flow.to);
 const curve=useMemo(()=>{if(!from||!to)return null; const a=from.position,b=to.position; return new THREE.QuadraticBezierCurve3(new THREE.Vector3(a[0],.85,a[2]),new THREE.Vector3((a[0]+b[0])/2,1.7,(a[2]+b[2])/2),new THREE.Vector3(b[0],.85,b[2]));},[from,to]);
 useFrame((_,delta)=>{if(paused||!ref.current||!curve)return;t.current=(t.current+delta*(.08+flow.volume/500))%1;ref.current.position.copy(curve.getPoint(t.current));});
 if(!curve)return null; return <mesh ref={ref}><sphereGeometry args={[.11,14,14]}/><meshStandardMaterial color={flowColor[flow.kind]} emissive={flowColor[flow.kind]} emissiveIntensity={.8}/></mesh>;
}

function Scene({areas,flows,selected,setSelected,kinds,paused}:{areas:Area[];flows:Flow[];selected:string;setSelected:(id:string)=>void;kinds:Kind[];paused:boolean}){
 const areasById=useMemo(()=>new Map(areas.map(area=>[area.id,area])),[areas]);
 return <><color attach="background" args={["#09090b"]}/><fog attach="fog" args={["#09090b",16,34]}/><ambientLight intensity={.9}/><directionalLight position={[7,12,8]} intensity={1.6}/><gridHelper args={[24,24,"#27272a","#18181b"]}/>
 {areas.map(area=><group key={area.id} position={[area.position[0],area.size[1]/2,area.position[2]]}><RoundedBox args={area.size} radius={.15} smoothness={4} onClick={event=>{event.stopPropagation();setSelected(area.id)}}><meshStandardMaterial color={statusColor[area.status]} emissive={statusColor[area.status]} emissiveIntensity={selected===area.id?.35:.08}/></RoundedBox><Html position={[0,1,0]} center distanceFactor={12}><button type="button" onClick={()=>setSelected(area.id)} className="rounded border border-white/10 bg-zinc-950/90 px-2 py-1 text-[10px] font-semibold text-white">{area.name}</button></Html></group>)}
 {flows.filter(flow=>kinds.includes(flow.kind)).map(flow=>{const from=areasById.get(flow.from),to=areasById.get(flow.to); if(!from||!to)return null; return <React.Fragment key={flow.id}><Line points={[[from.position[0],.85,from.position[2]],[to.position[0],.85,to.position[2]]]} color={flowColor[flow.kind]} transparent opacity={.22} lineWidth={1}/>{Array.from({length:Math.max(1,Math.min(3,Math.ceil(flow.volume/10)))},(_,index)=><FlowDot key={index} flow={flow} paused={paused} index={index} areasById={areasById}/>)}</React.Fragment>})}
 <OrbitControls makeDefault enableDamping minDistance={9} maxDistance={25} maxPolarAngle={Math.PI/2.05}/></>;
}

export default function App(){
 const [snapshot,setSnapshot]=useState<Snapshot|null>(null); const [events,setEvents]=useState<TwinEvent[]>([]); const [selected,setSelected]=useState(""); const [kinds,setKinds]=useState<Kind[]>(["supply","medication"]); const [paused,setPaused]=useState(false); const [loading,setLoading]=useState(true); const [refreshing,setRefreshing]=useState(false); const [error,setError]=useState<string|null>(null); const sinceRef=useRef<string|null>(null);
 const loadTwin=useCallback(async(initial=false)=>{if(initial)setLoading(true);else setRefreshing(true); try{const [snapshotResponse,eventsResponse]=await Promise.all([fetch("/api/twin/hospital",{cache:"no-store"}),fetch(`/api/twin/events?limit=12${sinceRef.current?`&since=${encodeURIComponent(sinceRef.current)}`:""}`,{cache:"no-store"})]); if(!snapshotResponse.ok)throw new Error(`Snapshot HTTP ${snapshotResponse.status}`); if(!eventsResponse.ok)throw new Error(`Events HTTP ${eventsResponse.status}`); const nextSnapshot=await snapshotResponse.json() as Snapshot; const eventBatch=await eventsResponse.json() as EventBatch; setSnapshot(nextSnapshot); setEvents(current=>{const unique=new Map([...eventBatch.events,...current].map(event=>[event.id,event])); return [...unique.values()].sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)).slice(0,12)}); sinceRef.current=eventBatch.generatedAt; setSelected(current=>current&&nextSnapshot.areas.some(area=>area.id===current)?current:(nextSnapshot.areas.find(area=>area.status==="critical")?.id??nextSnapshot.areas[0]?.id??"")); setError(null);}catch(err){setError(err instanceof Error?err.message:"No fue posible actualizar el gemelo digital.");}finally{setLoading(false);setRefreshing(false);}},[]);
 useEffect(()=>{void loadTwin(true); const timer=window.setInterval(()=>void loadTwin(false),5000); return()=>window.clearInterval(timer)},[loadTwin]);
 const current=useMemo(()=>snapshot?.areas.find(area=>area.id===selected)??null,[snapshot,selected]);
 const toggle=(kind:Kind)=>setKinds(currentKinds=>currentKinds.includes(kind)?(currentKinds.length===1?currentKinds:currentKinds.filter(value=>value!==kind)):[...currentKinds,kind]);
 if(loading&&!snapshot)return <div className="grid h-full w-full place-items-center bg-zinc-950 text-zinc-400"><div className="flex items-center gap-2 text-xs"><RefreshCw className="h-4 w-4 animate-spin"/>Cargando gemelo digital…</div></div>;
 if(!snapshot)return <div className="grid h-full w-full place-items-center bg-zinc-950 p-6 text-zinc-300"><div className="max-w-sm rounded border border-zinc-800 bg-zinc-900 p-4 text-sm"><div className="flex items-center gap-2 font-semibold"><WifiOff className="h-4 w-4 text-amber-400"/>Gemelo digital no disponible</div><p className="mt-2 text-xs text-zinc-500">{error??"Sin datos."}</p><button type="button" onClick={()=>void loadTwin(true)} className="mt-3 rounded border border-zinc-700 px-3 py-1.5 text-xs hover:bg-zinc-800">Reintentar</button></div></div>;
 return <div className="flex h-full w-full flex-col overflow-hidden bg-zinc-950 text-zinc-100"><header className="flex flex-wrap items-center justify-between gap-2 border-b border-zinc-800 px-3 py-2"><div><div className="flex items-center gap-2 text-sm font-semibold"><Activity className="h-4 w-4 text-cyan-400"/>Hospital Digital Twin · Abastecimiento<span className="inline-flex items-center gap-1 text-[9px] font-normal text-zinc-500"><Wifi className="h-3 w-3"/>{snapshot.source==="remote"?"FUENTE REAL":"DEMO"}</span></div><div className="text-[10px] text-zinc-500">TwinDataSource · snapshot + eventos · actualización cada 5 s</div></div><div className="flex flex-wrap gap-1">{(["supply","medication","patient","data"] as Kind[]).map(kind=><button type="button" key={kind} onClick={()=>toggle(kind)} className={`rounded border px-2 py-1 text-[10px] ${kinds.includes(kind)?"border-zinc-500 bg-zinc-700":"border-zinc-800 bg-zinc-900 text-zinc-500"}`}>{labels[kind]}</button>)}<button type="button" onClick={()=>setPaused(value=>!value)} className="grid h-7 w-7 place-items-center rounded border border-zinc-700 bg-zinc-900" title={paused?"Reanudar flujos":"Pausar flujos"}>{paused?<Play className="h-3.5 w-3.5"/>:<Pause className="h-3.5 w-3.5"/>}</button><button type="button" onClick={()=>void loadTwin(false)} className="grid h-7 w-7 place-items-center rounded border border-zinc-700 bg-zinc-900" title="Actualizar"><RefreshCw className={`h-3.5 w-3.5 ${refreshing?"animate-spin":""}`}/></button></div></header>{error&&<div className="flex items-center gap-2 border-b border-amber-900/30 bg-amber-950/20 px-3 py-1.5 text-[10px] text-amber-300"><AlertTriangle className="h-3 w-3"/>Última actualización falló: {error}. Se conserva el último estado válido.</div>}<div className="grid min-h-0 flex-1 grid-cols-[minmax(0,1fr)_240px] max-[760px]:grid-cols-1"><div className="min-h-[260px]"><Canvas camera={{position:[13,11,14],fov:48}} dpr={[1,1.5]}><Scene areas={snapshot.areas} flows={snapshot.flows} selected={selected} setSelected={setSelected} kinds={kinds} paused={paused}/></Canvas></div><aside className="overflow-auto border-l border-zinc-800 p-3 max-[760px]:border-l-0 max-[760px]:border-t">{current&&<><div className="text-[9px] uppercase tracking-[.16em] text-zinc-500">Área seleccionada</div><div className="mt-1 text-lg font-semibold">{current.name}</div><div className="mt-3 grid grid-cols-2 gap-2"><Metric label="Stock sano" value={formatMetric(current.metrics.stockHealth,"%")}/><Metric label="Actividad" value={formatMetric(current.metrics.activity)}/><Metric label="Ocupación" value={formatMetric(current.metrics.occupancy,"%")}/><Metric label="Pendientes" value={formatMetric(current.metrics.pending)}/></div><div className="mt-3 rounded border border-zinc-800 bg-zinc-900/60 p-2.5 text-[10px] leading-relaxed text-zinc-400">Estado: <strong style={{color:statusColor[current.status]}}>{current.status==="critical"?"CRÍTICO":current.status==="attention"?"ATENCIÓN":"NORMAL"}</strong><br/>Fuente: {snapshot.source==="remote"?"integración externa de solo lectura":"proveedor demo de Fase 2"}.</div></>}<div className="mt-4 border-t border-zinc-800 pt-3"><div className="mb-2 text-[9px] uppercase tracking-[.16em] text-zinc-500">Eventos recientes</div><div className="space-y-1.5">{events.slice(0,5).map(event=><div key={event.id} className="rounded border border-zinc-800 bg-zinc-900/50 p-2"><div className="flex items-center justify-between gap-2"><span className="truncate text-[10px] text-zinc-300">{eventLabel(event)}</span><span className="h-1.5 w-1.5 shrink-0 rounded-full" style={{background:statusColor[event.severity]}}/></div><div className="mt-0.5 text-[9px] text-zinc-600">{new Date(event.occurredAt).toLocaleTimeString()}</div></div>)}{events.length===0&&<div className="text-[10px] text-zinc-600">Sin eventos nuevos.</div>}</div></div></aside></div></div>;
}
function formatMetric(value:number|undefined,suffix=""){return typeof value==="number"?`${Math.round(value)}${suffix}`:"—"}
function eventLabel(event:TwinEvent){if(event.type==="inventory.low")return `Inventario bajo · ${event.areaId??"área"}`; if(event.type==="medication.moved")return `Medicamento · ${event.from??"?"} → ${event.to??"?"}`; if(event.type==="supply.moved")return `Abastecimiento · ${event.from??"?"} → ${event.to??"?"}`; if(event.type==="patient.moved")return `Paciente · ${event.from??"?"} → ${event.to??"?"}`; if(event.type==="operating_room.delayed")return `Retraso · ${event.areaId??"quirófano"}`; return event.type}
function Metric({label,value}:{label:string;value:string}){return <div className="rounded border border-zinc-800 bg-zinc-900/70 p-2"><div className="text-[9px] uppercase text-zinc-500">{label}</div><div className="mt-1 text-lg font-semibold tabular-nums">{value}</div></div>}
